import "server-only";

/**
 * Apple Root CA - G3, DER encoded, base64'd.
 *
 * Every receipt Apple signs chains up to this certificate, so it is the
 * anchor the whole in-app purchase path rests on: verifying a receipt
 * means proving its certificate chain ends HERE, at a key only Apple
 * holds. Without that check a forged receipt with an attacker's own
 * certificate would verify against itself perfectly, and anyone could
 * mint free minutes.
 *
 * Embedded rather than read from disk (serverless has no reliable
 * working directory) and rather than fetched at runtime (a network
 * dependency in the middle of a payment, and a fetch that could be
 * intercepted is exactly the thing a root certificate exists to prevent).
 *
 * From https://www.apple.com/certificateauthority/AppleRootCA-G3.cer
 * SHA-256 63:34:3A:BF:B8:9A:6A:03:EB:B5:7E:9B:3F:5F:A7:BE:7C:4F:5C:75:6F:30:17:B3:A8:C4:88:C3:65:3E:91:79
 * Self-signed, valid to 2039. Verify with:
 *   openssl x509 -inform DER -in AppleRootCA-G3.cer -noout -fingerprint -sha256
 */
const APPLE_ROOT_CA_G3_BASE64 = "";

export const APPLE_ROOT_CERTIFICATES: Buffer[] = [
  Buffer.from(APPLE_ROOT_CA_G3_BASE64, "base64"),
];
